return ['domain'=>'zinn-backups','plural-forms'=>'nplurals=3; plural=(n==1 ? 0 : n%10>=2 && n%10<=4 && (n%100<12 || n%100>14) ? 1 : 2);','language'=>'pl_PL','project-id-version'=>'zinn-backups','pot-creation-date'=>'2026-10-08T09:17:23+00:00','po-revision-date'=>'2026-10-08T09:17:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Backups'=>'Zinn® Backups','https://zinndigital.com/wordpress-plugins/zinn-backups'=>'https://zinndigital.com/wordpress-plugins/zinn-backups','Backs up your WordPress files and database to your own storage — Dropbox, Google Drive, Cloudflare R2, Amazon S3 or any S3-compatible bucket — restores them in one go, and imports backups made by other backup and migration plugins.'=>'Tworzy kopię zapasową twoich plików i bazy danych WordPress we własnym magazynie — Dropbox, Google Drive, Cloudflare R2, Amazon S3 lub dowolnym zasobniku zgodnym z S3 — przywraca je za jednym razem oraz importuje kopie zapasowe utworzone przez inne wtyczki do tworzenia kopii i migracji.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Backups'=>'Kopie zapasowe','Get Pro: schedules, several storages, encryption'=>'Kup Pro: harmonogramy, wiele miejsc docelowych, szyfrowanie','Working…'=>'Przetwarzanie…','Finished'=>'Zakończono','Failed'=>'Nieudane','Cancelled'=>'Anulowano','Cancel'=>'Anuluj','Restore'=>'Przywróć','Delete'=>'Usuń','Delete this backup from your storage? This cannot be undone.'=>'Usunąć tę kopię zapasową z twojego magazynu? Tej operacji nie można cofnąć.','No backups yet. Press “Back up now” to make the first one.'=>'Brak kopii zapasowych. Kliknij „Utwórz kopię zapasową teraz”, aby utworzyć pierwszą.','Reading your storage…'=>'Odczytywanie twojego miejsca na dysku…','a complete backup, as opposed to an incremental oneFull backup'=>'Pełna kopia zapasowa','a backup holding only what changed since an earlier oneIncremental backup'=>'Kopia przyrostowa','Encrypted'=>'Zaszyfrowane','From another site'=>'Z innej witryny','Database'=>'Baza danych','Files'=>'Pliki','Uploading %1$s: %2$s%%'=>'Przesyłanie %1$s: %2$s%%','Sign in to Dropbox in the window that opened, then paste the code Dropbox shows you:'=>'Zaloguj się do Dropboxa w otwartym oknie, a następnie wklej kod wyświetlony przez Dropbox:','Saved.'=>'Zapisano.','Remove this destination from the plugin? The backups stored in it are not deleted.'=>'Usunąć to miejsce docelowe z wtyczki? Zapisane w nim kopie zapasowe nie zostaną usunięte.','Reload the page to see the restored site.'=>'Odśwież stronę, aby zobaczyć przywróconą witrynę.','Storage'=>'Pamięć','Import & migrate'=>'Importuj i migruj','Settings'=>'Ustawienia','Sections'=>'Sekcje','Google Drive is connected.'=>'Dysk Google jest połączony.','Google Drive could not be connected.'=>'Nie udało się połączyć z Google Drive.','Details'=>'Szczegóły','Back up now'=>'Utwórz kopię zapasową teraz','Backups go to your own storage, not this server. <a href="%s">Connect your storage</a> first.'=>'Kopie zapasowe trafiają do twojego własnego magazynu danych, a nie na ten serwer. Najpierw <a href="%s">połącz swój magazyn danych</a>.','What to back up'=>'Co uwzględnić w kopii zapasowej','Files and database'=>'Pliki i baza danych','Database only'=>'Tylko baza danych','Files only'=>'Tylko pliki','Note (optional)'=>'Notatka (opcjonalnie)','Each part is uploaded to your storage and removed from this server before the next one is made, so the backup never takes up room on your hosting.'=>'Każda część jest przesyłana do twojego magazynu i usuwana z tego serwera przed utworzeniem następnej, dzięki czemu kopia zapasowa nigdy nie zajmuje miejsca na twoim hostingu.','Your backups'=>'Twoje kopie zapasowe','Refresh'=>'Odśwież','Restore this backup'=>'Przywróć tę kopię zapasową','Passphrase'=>'Hasło','I understand this replaces this site’s files and database with the backup’s. Files that are not in the backup are kept.'=>'Rozumiem, że spowoduje to zastąpienie plików i bazy danych tej witryny danymi z kopii zapasowej. Pliki, których nie ma w kopii zapasowej, zostaną zachowane.','Recent activity'=>'Ostatnia aktywność','Backup'=>'Kopia zapasowa','Restore / import'=>'Przywróć / importuj','Running'=>'Uruchomiono','Your storage'=>'Twoje miejsce na dysku' . "\0" . 'Twoje miejsca docelowe pamięci' . "\0" . 'Twoje miejsca docelowe pamięci','No storage yet. Choose where your backups go below.'=>'Brak pamięci podręcznej. Wybierz poniżej, gdzie mają trafiać twoje kopie zapasowe.','Ready'=>'Gotowe','Not connected'=>'Nie połączono','Connect'=>'Połącz','Test'=>'Testuj','Edit'=>'Edytuj','Remove'=>'Usuń','Add storage'=>'Dodaj pamięć masową','Backups go to one storage destination. To use a different one, edit or remove the one above.'=>'Kopie zapasowe trafiają do jednego miejsca docelowego. Aby użyć innego, edytuj lub usuń powyższe.','Kind of storage'=>'Rodzaj pamięci masowej','Name (for you)'=>'Nazwa (dla ciebie)','Provider'=>'Dostawca','Cloudflare account id'=>'Identyfikator konta Cloudflare','Endpoint address'=>'Adres punktu końcowego','Region'=>'Region','Bucket'=>'Zasobnik','Access key id'=>'Identyfikator klucza dostępu','Secret access key'=>'Tajny klucz dostępu','Leave empty to keep the saved key'=>'Pozostaw puste, aby zachować zapisany klucz','For Cloudflare R2: in the Cloudflare dashboard open R2, create a bucket, then “Manage R2 API tokens” → create a token with Object Read & Write for that bucket, and copy the access key id and secret here.'=>'W przypadku Cloudflare R2: w kokpicie Cloudflare otwórz R2, utwórz bucket, następnie „Manage R2 API tokens” → utwórz token z uprawnieniami Object Read & Write dla tego bucketa i skopiuj tutaj access key id oraz secret.','Dropbox app key'=>'Klucz aplikacji Dropbox','Create an app at dropbox.com/developers/apps (Scoped access, App folder) with the files.content.read, files.content.write and files.metadata.read permissions, and copy its App key here. Save, then press Connect.'=>'Utwórz aplikację pod adresem dropbox.com/developers/apps (Scoped access, App folder) z uprawnieniami files.content.read, files.content.write oraz files.metadata.read i skopiuj tutaj jej App key. Zapisz, a następnie naciśnij Connect.','OAuth client id'=>'Identyfikator klienta OAuth','OAuth client secret'=>'Klucz tajny klienta OAuth','Leave empty to keep the saved secret'=>'Pozostaw puste, aby zachować zapisany sekret','In Google Cloud Console, enable the Google Drive API, then create an OAuth client of type “Web application” with this address as an authorised redirect URI:'=>'W Google Cloud Console włącz Google Drive API, a następnie utwórz klienta OAuth typu „Web application” z tym adresem jako autoryzowanym identyfikatorem URI przekierowania:','Save, then press Connect. The plugin only sees the files it creates.'=>'Zapisz, a następnie naciśnij Połącz. Wtyczka widzi tylko pliki, które sama tworzy.','Folder inside the storage (optional)'=>'Folder w pamięci masowej (opcjonalnie)','Save storage'=>'Oszczędzaj miejsce','Import a backup from another plugin or host'=>'Zaimportuj kopię zapasową z innej wtyczki lub hosta','Bring a site in from a backup made by UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate, or any zip/tar archive of a WordPress site with its .sql dump. The content goes into wp-content and the database replaces this site’s; addresses are changed to this site’s automatically.'=>'Zaimportuj witrynę z kopii zapasowej utworzonej przez UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate lub dowolne archiwum zip/tar witryny WordPress wraz z jej zrzutem .sql. Zawartość trafia do wp-content, a baza danych zastępuje bazę tej witryny; adresy są automatycznie zmieniane na adresy tej witryny.','Upload from your computer'=>'Prześlij ze swojego komputera','Choose every file of the backup at once (UpdraftPlus makes several). Large files are sent in small pieces, so your host’s upload limit does not apply.'=>'Wybierz wszystkie pliki kopii zapasowej naraz (UpdraftPlus tworzy ich kilka). Duże pliki są wysyłane w małych fragmentach, więc limit wysyłania twojego hostingu nie ma zastosowania.','Or from links (Google Drive, Dropbox or any download address)'=>'Lub z linków (Google Drive, Dropbox lub dowolny adres pobierania)','One link per line. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link; turn sharing off again afterwards.'=>'Jeden link w wierszu. W przypadku Google Drive i Dropbox udostępnij plik „każdemu, kto ma link” i wklej ten link; później wyłącz ponownie udostępnianie.','Or a file already on this server'=>'Lub plik znajdujący się już na tym serwerze','Upload archives by FTP or your host’s file manager into %s and reload this page.'=>'Prześlij archiwa przez FTP lub menedżer plików swojego hostingu do %s i odśwież tę stronę.','Or a deploy code from another site'=>'Lub kod wdrożenia z innej witryny','If another site gave you a Zinn® Backups deploy code, paste it here to copy that backup onto this site without sharing its storage keys. A code works for a few hours; treat it like a password.'=>'Jeśli inna witryna przekazała Ci kod wdrożenia Zinn® Backups, wklej go tutaj, aby skopiować tę kopię zapasową na tę witrynę bez udostępniania jej kluczy pamięci masowej. Kod działa przez kilka godzin; traktuj go jak hasło.','Passphrase (only if that backup is encrypted)'=>'Hasło (tylko jeśli ta kopia zapasowa jest zaszyfrowana)','Import'=>'Importuj','I understand the import replaces this site’s content and database. After it, sign in with an account from the imported site.'=>'Rozumiem, że import zastępuje zawartość i bazę danych tej witryny. Następnie zaloguj się za pomocą konta z zaimportowanej witryny.','Moving to Zinn® hosting?'=>'Przenosisz się na hosting Zinn®?','Zinn Digital® can move your site for you from your old host. If your old host gives you no FTP, SSH or control-panel access, install Zinn® Migrate on the old site; it makes one archive you can import here or hand to Zinn®.'=>'Zinn Digital® może przenieść twoją witrynę ze starego hostingu. Jeśli twój stary hosting nie zapewnia dostępu do FTP, SSH ani panelu zarządzania, zainstaluj Zinn® Migrate na starej witrynie; utworzy ono jedno archiwum, które możesz zaimportować tutaj lub przekazać do Zinn®.','What goes into a backup'=>'Co wchodzi w skład kopii zapasowej','Include WordPress’s own files (wp-admin, wp-includes). Usually not needed: WordPress can always be reinstalled.'=>'Dołącz własne pliki WordPress (wp-admin, wp-includes). Zwykle niepotrzebne: WordPress można zawsze zainstalować ponownie.','Also leave out these folders or files (one per line, relative to the WordPress folder)'=>'Pomiń również te foldery lub pliki (jeden w wierszu, względem folderu WordPress)','Always left out: caches, update scratch space, and other backup plugins’ own archive folders:'=>'Zawsze pomijane: pamięci podręczne, przestrzeń robocza aktualizacji oraz własne foldery archiwów innych wtyczek do kopii zapasowych:','Size of each part (MB)'=>'Rozmiar każdej części (MB)','Save settings'=>'Zapisz ustawienia','A backup part could not be opened for writing. Check that wp-content has free space.'=>'Część kopii zapasowej nie mogła zostać otwarta do zapisu. Sprawdź, czy w katalogu wp-content jest wolne miejsce.','A backup part could not be written. Check that wp-content has free space.'=>'Część kopii zapasowej nie mogła zostać zapisana. Sprawdź, czy katalog wp-content ma wolne miejsce.','Connect a storage destination on the Storage tab first: backups are kept in your own storage, not on this server.'=>'Najpierw połącz miejsce docelowe w zakładce Storage: kopie zapasowe są przechowywane w twoim własnym magazynie danych, a nie na tym serwerze.','Multisite networks are not supported yet.'=>'Sieci witryn (multisite) nie są jeszcze obsługiwane.','This server’s PHP has no ZipArchive extension. Ask your host to enable it.'=>'PHP na tym serwerze nie posiada rozszerzenia ZipArchive. Poproś swojego usługodawcę hostingowego o jego włączenie.','Starting'=>'Uruchamianie','Listing files'=>'Tworzenie listy plików','Backing up the database'=>'Tworzenie kopii zapasowej bazy danych','Packing files'=>'Pakowanie plików','Uploading to your storage'=>'Przesyłanie do twojego magazynu','Finishing'=>'Kończenie','The backup reached an unknown stage.'=>'Kopia zapasowa osiągnęła nieznany etap.','Backup %s started.'=>'Kopia zapasowa %s została rozpoczęta.','Found %1$s files (%2$s).'=>'Znaleziono %1$s plików (%2$s).','Database: %1$d tables, %2$s rows, %3$s compressed.'=>'Baza danych: %1$d tabel, %2$s wierszy, %3$s skompresowano.','Backup complete: %1$s stored in %2$d destination.'=>'Kopia zapasowa ukończona: %1$s zapisano w %2$d miejscu docelowym.' . "\0" . 'Kopia zapasowa ukończona: %1$s zapisano w %2$d lokalizacjach.' . "\0" . 'Kopia zapasowa ukończona: %1$s zapisano w %2$d lokalizacjach.','Some parts already uploaded could not be removed from your storage; they are in an incomplete backup folder and are never offered for restore.'=>'Niektórych przesłanych już części nie udało się usunąć z twojego magazynu; znajdują się one w folderze niekompletnej kopii zapasowej i nigdy nie są proponowane do przywrócenia.','A storage destination was removed while the backup was running.'=>'Miejsce docelowe pamięci masowej zostało usunięte podczas wykonywania kopii zapasowej.','That is not a backup folder.'=>'To nie jest folder kopii zapasowej.','That storage destination is no longer saved on this site.'=>'To miejsce docelowe pamięci nie jest już zapisane w tej witrynie.','Later incremental backups are built on this one. Delete those first.'=>'Kolejne przyrostowe kopie zapasowe bazują na tej. Usuń je najpierw.','This file is not an encrypted Zinn® Backups file.'=>'Ten plik nie jest zaszyfrowanym plikiem Zinn® Backups.','The backup could not be decrypted: the passphrase is wrong or the file is damaged.'=>'Nie udało się odszyfrować kopii zapasowej: hasło jest nieprawidłowe lub plik jest uszkodzony.','The encrypted backup file is incomplete.'=>'Zaszyfrowany plik kopii zapasowej jest niekompletny.','The database file could not be written. Check that wp-content has free space.'=>'Nie udało się zapisać pliku bazy danych. Sprawdź, czy w katalogu wp-content jest wolne miejsce.','That is not a deploy code. A deploy code starts with zbdeploy1.'=>'To nie jest kod wdrożenia. Kod wdrożenia zaczyna się od zbdeploy1.','That deploy code is damaged. Copy it again from the other site.'=>'Ten kod wdrożenia jest uszkodzony. Skopiuj go ponownie z drugiej witryny.','The deploy code has expired or its backup was deleted. Make a new code on the other site.'=>'Kod wdrożenia wygasł lub jego kopia zapasowa została usunięta. Wygeneruj nowy kod na drugiej witrynie.','That deploy code does not point at a Zinn® Backups backup.'=>'Ten kod wdrożenia nie wskazuje na kopię zapasową Zinn® Backups.','The deploy code has expired. Make a new code on the other site.'=>'Kod wdrożenia wygasł. Wygeneruj nowy kod w drugiej witrynie.','The server stopped honouring partial downloads. Start the import again.'=>'Serwer przestał obsługiwać częściowe pobieranie. Rozpocznij import ponownie.','The link opened a web page instead of a file. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link.'=>'Link otworzył stronę internetową zamiast pliku. W przypadku Google Drive i Dropbox udostępnij plik „każdej osobie mającej link” i wklej ten link.','The link answered with HTTP %d.'=>'Link odpowiedział kodem HTTP %d.','The file list could not be written.'=>'Nie udało się zapisać listy plików.','The storage service could not be reached: %s'=>'Nie udało się połączyć z usługą pamięci masowej: %s','%1$s answered with HTTP %2$d: %3$s'=>'%1$s odpowiedział statusem HTTP %2$d: %3$s','no details given'=>'Nie podano szczegółów','You are not allowed to manage backups.'=>'Nie masz uprawnień do zarządzania kopiami zapasowymi.','Tick the box to confirm that the restore replaces this site’s files and database.'=>'Zaznacz pole, aby potwierdzić, że przywrócenie zastąpi pliki i bazę danych tej witryny.','Save the destination first.'=>'Najpierw zapisz miejsce docelowe.','Connected: a test file was written and removed.'=>'Połączono: plik testowy został zapisany i usunięty.','Enter the app key of your Dropbox app first (see the steps beside the form).'=>'Wprowadź najpierw klucz aplikacji Dropbox (zobacz kroki obok formularza).','This kind of storage does not sign in.'=>'Ten rodzaj pamięci masowej nie loguje się.','The sign-in expired. Press Connect again.'=>'Logowanie wygasło. Naciśnij ponownie Połącz.','Dropbox is connected.'=>'Dropbox jest połączony.','Settings saved.'=>'Ustawienia zapisane.','Another backup, restore or import is running. Wait for it to finish, or cancel it.'=>'Inna kopia zapasowa, przywracanie lub importowanie jest w toku. Poczekaj, aż się zakończy, lub anuluj operację.','The upload was not started properly. Start again.'=>'Przesyłanie nie rozpoczęło się poprawnie. Zacznij od nowa.','The chunk did not arrive. Your server may limit upload sizes; try again.'=>'Fragment nie dotarł. Twój serwer może ograniczać rozmiar przesyłanych plików; spróbuj ponownie.','Tick the box to confirm that the import replaces this site’s content and database.'=>'Zaznacz to pole, aby potwierdzić, że import zastąpi zawartość i bazę danych tej witryny.','Choose an archive to import: upload it, paste a link, or pick one from the import folder.'=>'Wybierz archiwum do zaimportowania: prześlij je, wklej link lub wybierz plik z folderu importu.','Hosting customer? Get %1$d%% off %2$s'=>'Klient hostingu? Odbierz %1$d%% zniżki na %2$s','As a Zinn Digital® hosting customer you get a personal code for %d%% off your first payment. Renewals are at the normal price.'=>'Jako klient hostingu Zinn Digital® otrzymujesz osobisty kod z rabatem %d%% na pierwszą płatność. Odnowienia są w standardowej cenie.','Get my %d%% code and go to checkout'=>'Odbierz mój kod na %d%% i przejdź do kasy','Sorry, you are not allowed to do that.'=>'Przepraszamy, nie masz uprawnień, aby to zrobić.','This discount is for customers with a paid hosting plan in good standing. Free trials do not qualify.'=>'Ten rabat jest przeznaczony dla klientów posiadających aktywny i opłacony plan hostingowy. Bezpłatne okresy próbne nie kwalifikują się.','You have already used your hosting-customer discount for this plugin.'=>'Wykorzystałeś już swój rabat klienta hostingu na tę wtyczkę.','We could not get your code just now. Please try again in a few minutes.'=>'Przed chwilą nie udało się pobrać twojego kodu. Spróbuj ponownie za kilka minut.','Reading the backup'=>'Odczytywanie kopii zapasowej','Downloading the archive'=>'Pobieranie archiwum','Recognising the archive'=>'Rozpoznawanie archiwum','Restoring files'=>'Przywracanie plików','Downloading the database'=>'Pobieranie bazy danych','Restoring the database'=>'Przywracanie bazy danych','Updating the site address'=>'Aktualizowanie adresu witryny','Switching to the restored database'=>'Przełączanie na przywróconą bazę danych','The restore reached an unknown stage.'=>'Przywracanie osiągnęło nieznany etap.','This folder has no complete Zinn® Backups backup in it (the manifest is missing).'=>'Ten folder nie zawiera kompletnej kopii zapasowej Zinn® Backups (brakuje manifestu).','This backup is encrypted. Enter its passphrase to restore it.'=>'Ta kopia zapasowa jest zaszyfrowana. Wpisz hasło, aby ją przywrócić.','This incremental backup needs backup %s, which is no longer in the storage.'=>'Ta przyrostowa kopia zapasowa wymaga kopii zapasowej %s, której nie ma już w magazynie.','Restoring the backup of %1$s (%2$d file parts).'=>'Przywracanie kopii zapasowej %1$s (%2$d części pliku).','%1$s file could not be overwritten because this site is not allowed to change it, and was left as it is: %2$s'=>'Nie udało się zastąpić pliku %1$s, ponieważ ta witryna nie ma uprawnień do jego modyfikacji, i został pozostawiony w obecnym stanie: %2$s' . "\0" . 'Nie udało się nadpisać %1$s plików, ponieważ ta witryna nie ma uprawnień do ich modyfikacji, i zostały one pozostawione bez zmian: %2$s' . "\0" . 'Nie udało się nadpisać %1$s plików, ponieważ ta witryna nie ma uprawnień do ich modyfikacji, i zostały one pozostawione bez zmian: %2$s','Restored %s files.'=>'Przywrócono %s plików.','%s did not match its checksum after downloading. The copy in storage may be damaged.'=>'%s nie zgadza się ze swoją sumą kontrolną po pobraniu. Kopia w magazynie może być uszkodzona.','%s did not arrive. Upload it again.'=>'Element %s nie dotarł. Prześlij go ponownie.','Recognised: %s.'=>'Rozpoznano: %s.','Imported %1$s files into wp-content (%2$s left out: caches, drop-ins and other backup plugins’ folders).'=>'Zaimportowano %1$s plików do wp-content (pominięto %2$s: pamięci podręczne, drop-iny i foldery innych wtyczek do tworzenia kopii zapasowych).','The archive has no database dump, so only files were imported.'=>'Archiwum nie zawiera zrzutu bazy danych, dlatego zaimportowano tylko pliki.','Database restored into %d temporary tables.'=>'Baza danych została przywrócona do %d tabel tymczasowych.','%s has no WordPress tables in it and was skipped.'=>'%s nie zawiera tabel WordPress i został pominięty.','The backup’s database has no WordPress tables, so nothing was replaced.'=>'Baza danych kopii zapasowej nie zawiera tabel WordPress, więc nic nie zostało zastąpione.','This backup is of a multisite network. Restoring a network into a single site is not supported.'=>'Ta kopia zapasowa pochodzi z sieci witryn (multisite). Przywracanie sieci do pojedynczej witryny nie jest obsługiwane.','Moving the content from %1$s to %2$s.'=>'Przenoszenie zawartości z %1$s do %2$s.','Restore complete. If you are signed out, sign in with an account from the restored site.'=>'Przywracanie ukończone. Jeśli wylogowano cię, zaloguj się za pomocą konta z przywróconej witryny.','Restore complete.'=>'Przywracanie zakończone.','%1$s — trying again in %2$d seconds.'=>'%1$s — ponowna próba za %2$d s.','Cancelled.'=>'Anulowano.','Backups go to one storage destination. Edit or remove the one you have to use a different one.'=>'Kopie zapasowe trafiają do jednego miejsca docelowego. Edytuj lub usuń istniejące, aby użyć innego.','The database file could not be opened.'=>'Nie udało się otworzyć pliku bazy danych.','The database refused a statement from the backup: %1$s (%2$s…)'=>'Baza danych odrzuciła instrukcję z kopii zapasowej: %1$s (%2$s…)','The restored tables could not be swapped in: %s. Your site is unchanged.'=>'Nie udało się podmienić przywróconych tabel: %s. Twoja witryna pozostała bez zmian.','There is no writable folder for temporary backup files. Make wp-content writable and try again.'=>'Brak zapisywalnego katalogu na tymczasowe pliki kopii zapasowej. Nadaj uprawnienia do zapisu dla wp-content i spróbuj ponownie.','Could not create a folder for this job.'=>'Nie udało się utworzyć folderu dla tego zadania.','%s — guides and services'=>'%s — poradniki i usługi','User guides'=>'Przewodniki użytkownika','Read the %s user guide'=>'Przeczytaj podręcznik użytkownika %s','Hide this'=>'Ukryj to','Zinn® hosting for WordPress'=>'Hosting Zinn® dla WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, codzienne kopie zapasowe, bezpłatna migracja i panel kontrolny stworzony dla osób zarządzających więcej niż jedną witryną.','The Zinn® marketplace'=>'Rynek Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupuj i sprzedawaj istniejące strony, domeny i miejsca na linki, z pieniędzmi bezpiecznie zdeponowanymi do momentu, aż obie strony będą zadowolone.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — zatrudnij ludzi, którzy zajmują się tym zawodowo','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Nasz globalny rynek dla freelancerów: przeglądaj ponad 10 000 gotowych usług od autorów, projektantów, programistów i specjalistów SEO lub opublikuj projekt i pozwól im składać oferty.','See the Zinn Digital® release notes.'=>'Zobacz informacje o wydaniu Zinn Digital®.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Usługa aktualizacji Zinn® nie wygenerowała odnośnika do pobrania tej aktualizacji. Sprawdź, czy ta witryna może połączyć się z platformą Zinn®, a następnie spróbuj ponownie.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Nie udało się pobrać aktualizacji z usługi aktualizacji Zinn® (%s). Spróbuj ponownie za kilka minut.','The downloaded update failed its integrity check and was not installed.'=>'Pobrana aktualizacja nie przeszła pomyślnie sprawdzania integralności i nie została zainstalowana.','The zip archive could not be opened. It may be damaged or incomplete.'=>'Nie udało się otworzyć archiwum zip. Może być uszkodzone lub niekompletne.','This .wpress file uses a format we cannot read (it may be compressed or encrypted by All-in-One WP Migration). Export it again without encryption.'=>'Ten plik .wpress używa formatu, którego nie możemy odczytać (mógł zostać skompresowany lub zaszyfrowany przez All-in-One WP Migration). Wyeksportuj go ponownie bez szyfrowania.','This is a Duplicator “DupArchive” (.daf) file. In Duplicator, build the package again with the archive format set to ZIP, then import that.'=>'To jest plik Duplicator „DupArchive” (.daf). W Duplicatorze utwórz pakiet ponownie z formatem archiwum ustawionym na ZIP, a następnie go zaimportuj.','This UpdraftPlus database backup is encrypted. Decrypt it in UpdraftPlus (or turn off database encryption and back up again), then import it.'=>'Ta kopia zapasowa bazy danych UpdraftPlus jest zaszyfrowana. Odszyfruj ją w UpdraftPlus (lub wyłącz szyfrowanie bazy danych i utwórz kopię zapasową ponownie), a następnie ją zaimportuj.','Database dump'=>'Zrzut bazy danych','%s is not a backup archive we can read (zip, tar, tar.gz, .wpress, .sql or .sql.gz).'=>'%s nie jest archiwum kopii zapasowej, które możemy odczytać (zip, tar, tar.gz, .wpress, .sql lub .sql.gz).','Website archive'=>'Archiwum witryny','%s has no WordPress content (no wp-content folder and no database dump) in it.'=>'%s nie zawiera żadnych treści WordPress (brak folderu wp-content i brak zrzutu bazy danych).','This .wpress file is encrypted or compressed by All-in-One WP Migration. Export it again with encryption and compression switched off, then import that.'=>'Ten plik .wpress jest zaszyfrowany lub skompresowany przez All-in-One WP Migration. Wyeksportuj go ponownie z wyłączonym szyfrowaniem i kompresją, a następnie go zaimportuj.','Other S3-compatible storage'=>'Inny magazyn zgodny z S3','Cloudflare R2, Amazon S3 or S3-compatible'=>'Cloudflare R2, Amazon S3 lub zgodny z S3','The storage keys could not be read on this site. Enter the secret key again on the Storage tab.'=>'Nie udało się odczytać kluczy pamięci na tej stronie. Wprowadź tajny klucz ponownie w zakładce Pamięć.','This kind of storage is not known.'=>'Ten rodzaj pamięci masowej jest nieznany.','Choose a kind of storage.'=>'Wybierz rodzaj magazynu.','Enter the bucket name and the access key.'=>'Wprowadź nazwę zasobnika i klucz dostępu.','Enter your Cloudflare account id (or the full R2 endpoint).'=>'Wprowadź identyfikator swojego konta Cloudflare (lub pełny punkt końcowy R2).','Enter the endpoint address of your storage.'=>'Wprowadź adres punktu końcowego swojego magazynu danych.','Enter the OAuth client id from your Google Cloud project.'=>'Wprowadź OAuth client id ze swojego projektu Google Cloud.','Dropbox did not return a refresh token. Start the connection again.'=>'Dropbox nie zwrócił tokenu odświeżania. Rozpocznij połączenie ponownie.','Dropbox is not connected. Connect it again on the Storage tab.'=>'Dropbox nie jest połączony. Połącz go ponownie w zakładce Przechowywanie.','Google did not return a refresh token. Remove this site from your Google account’s third-party access and connect again.'=>'Google nie zwrócił tokenu odświeżania. Usuń tę witrynę z dostępu innych firm na swoim koncie Google i połącz się ponownie.','That file is not in Google Drive any more.'=>'Ten plik nie znajduje się już na Google Drive.','Google Drive is not connected. Connect it again on the Storage tab.'=>'Google Drive nie jest połączony. Połącz go ponownie w zakładce Pamięć.','The storage service did not start the upload.'=>'Usługa przechowywania nie rozpoczęła przesyłania.','The storage service sent a reply that could not be read.'=>'Usługa przechowywania wysłała odpowiedź, której nie można było odczytać.','A temporary backup file could not be read.'=>'Nie udało się odczytać tymczasowego pliku kopii zapasowej.','A deploy link is read-only.'=>'Link wdrożenia jest tylko do odczytu.','The deploy code has no link for a file this backup needs.'=>'Kod wdrożenia nie zawiera linku do pliku wymaganego przez tę kopię zapasową.','The deploy link'=>'Link do wdrożenia']];